def fit_tile(g):
    g=np.array(g); H,W=g.shape; z=(g==0)
    best=None
    for p in range(1,H+1):
        for pc in range(1,W+1):
            ref={}; ok=True
            for i in range(H):
                for j in range(W):
                    if z[i,j]: continue
                    k=((i%p),(j%pc)); v=int(g[i,j])
                    if k in ref and ref[k]!=v: ok=False; break
                    ref[k]=v
                if not ok: break
            if ok and (best is None or len(ref)<best[2]):
                best=(p,pc,len(ref),sorted(ref.items()))
    return best
